document.addEventListener("DOMContentLoaded",()=>{const e=[{title:"Yarn Preparation",description:"Cotton or silk yarns are prepared and stretched onto a wooden frame to ensure they are aligned tightly for the tying process.",image:"assets/culture.png"},{title:"Yarn Tying / Resist Binding",description:"Artisans meticulously tie sections of the yarn with rubber bindings or cotton threads according to a pre-calculated pattern. The tied areas will resist the dye.",image:"assets/travel_hidden.png"},{title:"Dyeing",description:"The tied bundles of yarn are immersed in a dye bath. The dye colors the exposed parts of the yarn, while the tied parts remain the original color.",image:"assets/heritage_temples.png"},{title:"Untying / Revealing",description:"Once the dyed yarn is dried, the ties are removed to reveal the un-dyed pattern underneath.",image:"assets/travel_mountains.png"},{title:"Repeating for Additional Colors",description:"For multi-colored ikats, the tying and dyeing process is repeated multiple times, requiring immense precision.",image:"assets/travel_deserts.png"},{title:"Weaving",description:"The dyed yarns are carefully arranged on the loom as the warp or weft (or both in double ikat). As weaving progresses, the intricate pattern slowly materializes.",image:"assets/hero_banner.png"},{title:"Finished Ikat Textile",description:"The final woven textile features the signature feathered edges where the dyed threads overlap, a hallmark of authentic handloom Ikat.",image:"assets/heritage_forts.png"}];let t=0;const i=document.getElementById("process-visualizer");!function n(){if(!i)return;let a="";e.forEach((e,i)=>{a+=`\n                <div class="step-container ${i===t?"active":""}" id="step-${i}">\n                    <div class="step-number">${i+1}</div>\n                    <h3 style="color: var(--text-light); margin-bottom: 15px; font-size: 1.6rem;">${e.title}</h3>\n                    <img src="${e.image}" alt="${e.title}" class="step-image" onerror="this.style.display='none'">\n                    <p style="color: var(--text-muted); font-size: 1.05rem; line-height: 1.6; max-width: 600px; margin: 0 auto;">${e.description}</p>\n                </div>\n            `}),a+=`\n            <div class="step-controls">\n                <button class="btn-step" id="prev-step" ${0===t?"disabled":""}>← Previous</button>\n                <div class="progress-dots">\n                    ${e.map((e,i)=>`<span class="progress-dot ${i===t?"active":""}"></span>`).join("")}\n                </div>\n                <button class="btn-step" id="next-step" ${t===e.length-1?"disabled":""}>Next →</button>\n            </div>\n        `,i.innerHTML=a;const s=document.getElementById("prev-step"),r=document.getElementById("next-step");s&&s.addEventListener("click",()=>{t>0&&(t--,n())}),r&&r.addEventListener("click",()=>{t<e.length-1&&(t++,n())})}();const n=[{name:"Chowka (Diamond)",description:"The classic geometric diamond shape, often interlocked or overlapping, forming the core identity of Pochampally designs.",image:"assets/culture.png"},{name:"Rumaal Design",description:"Inspired by the Telia Rumal handkerchiefs, these feature large grid-like structures with intricate motifs inside the squares.",image:"assets/travel_hidden.png"},{name:"Elephant Motif",description:"Traditional elephant figures rendered in a pixelated ikat style, symbolising royalty and strength.",image:"assets/heritage_temples.png"},{name:"Parrot Motif",description:"Stylised parrots often adorning the borders of sarees and dupattas, symbolising love and passion.",image:"assets/travel_mountains.png"}],a=[{title:"Single Ikat (Warp)",description:"Only the warp (vertical) yarns are tie-dyed before weaving. The weft remains a solid color. This produces a pattern that is visible but less complex.",image:"assets/travel_deserts.png"},{title:"Single Ikat (Weft)",description:"Only the weft (horizontal) yarns are tie-dyed. As the weaver passes the shuttle, the pattern is formed horizontally on the loom.",image:"assets/hero_banner.png"},{title:"Double Ikat",description:"Both warp and weft yarns are tie-dyed with extreme precision. The pattern only emerges perfectly when the dyed warp and weft intersect accurately during weaving. It requires masterful skill.",image:"assets/heritage_forts.png"}],s=document.getElementById("details-modal"),r=document.getElementById("modal-title"),o=document.getElementById("modal-desc"),d=document.getElementById("close-modal");d&&d.addEventListener("click",()=>{s.classList.remove("active")}),s&&s.addEventListener("click",e=>{e.target===s&&s.classList.remove("active")});const l=document.getElementById("pattern-gallery");l&&n.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.innerHTML=`\n                <img src="${e.image}" alt="${e.name}" class="fabric-image" onerror="this.style.display='none'">\n                <h3>${e.name}</h3>\n                <p style="color: var(--text-muted); font-size: 0.85rem; margin-top: auto;">Click to view details</p>\n            `,t.addEventListener("click",()=>{var t,i;t=e.name,i=e.description,r.textContent=t,o.textContent=i,s.classList.add("active")}),l.appendChild(t)});const c=document.getElementById("weaving-techniques");c&&a.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.style.cursor="default",t.innerHTML=`\n                <img src="${e.image}" alt="${e.title}" class="fabric-image" onerror="this.style.display='none'">\n                <h3>${e.title}</h3>\n                <p style="color: var(--text-light); font-size: 0.95rem; line-height: 1.6;">${e.description}</p>\n            `,c.appendChild(t)})});